#[inline]
pub unsafe fn lodepng_convert(
    mut out: *mut c_uchar,
    mut in_0: *const c_uchar,
    mut mode_out: *const LodePNGColorMode,
    mut mode_in: *const LodePNGColorMode,
    mut w: c_uint,
    mut h: c_uint,
) -> c_uint {
    let mut tree: ColorTree = ColorTree {
        children: [::core::ptr::null_mut::<ColorTree>(); 16],
        index: 0,
    };
    let numpixels: size_t = (w as size_t).wrapping_mul(h as size_t);

    let mode_in_ref = &*mode_in;
    let mode_out_ref = &*mode_out;

    if mode_in_ref.colortype as c_uint == LCT_PALETTE as c_int as c_uint
        && mode_in_ref.palette.is_null()
    {
        return 107 as c_uint;
    }

    if lodepng_color_mode_equal(mode_out, mode_in) != 0 {
        let numbytes: size_t = lodepng_get_raw_size(w, h, mode_in);
        lodepng_memcpy(out as *mut c_void, in_0 as *const c_void, numbytes);
        return 0 as c_uint;
    }

    let out_is_palette = mode_out_ref.colortype as c_uint == LCT_PALETTE as c_int as c_uint;
    let out_bitdepth = mode_out_ref.bitdepth;
    let in_bitdepth = mode_in_ref.bitdepth;
    let out_colortype = mode_out_ref.colortype as c_uint;

    let mut error: c_uint = 0;

    if out_is_palette {
        let mut palettesize: size_t = mode_out_ref.palettesize;
        let mut palette: *const c_uchar = mode_out_ref.palette;
        let mut palsize: size_t = (1 as size_t) << out_bitdepth;

        if palettesize == 0 {
            palettesize = mode_in_ref.palettesize;
            palette = mode_in_ref.palette;
            if mode_in_ref.colortype as c_uint == LCT_PALETTE as c_int as c_uint
                && in_bitdepth == out_bitdepth
            {
                let numbytes_0: size_t = lodepng_get_raw_size(w, h, mode_in);
                lodepng_memcpy(out as *mut c_void, in_0 as *const c_void, numbytes_0);
                return 0 as c_uint;
            }
        }

        if palettesize < palsize {
            palsize = palettesize;
        }

        color_tree_init(&raw mut tree);

        let mut i: size_t = 0;
        while i != palsize {
            let p = palette.wrapping_add(i.wrapping_mul(4));
            error = color_tree_add(
                &raw mut tree,
                *p.wrapping_add(0),
                *p.wrapping_add(1),
                *p.wrapping_add(2),
                *p.wrapping_add(3),
                i as c_uint,
            );
            if error != 0 {
                break;
            }
            i = i.wrapping_add(1);
        }
    }

    if error == 0 {
        if in_bitdepth == 16 && out_bitdepth == 16 {
            let mut i: size_t = 0;
            while i != numpixels {
                let mut r: c_ushort = 0;
                let mut g: c_ushort = 0;
                let mut b: c_ushort = 0;
                let mut a: c_ushort = 0;
                getPixelColorRGBA16(&raw mut r, &raw mut g, &raw mut b, &raw mut a, in_0, i, mode_in);
                rgba16ToPixel(out, i, mode_out, r, g, b, a);
                i = i.wrapping_add(1);
            }
        } else if out_bitdepth == 8 && out_colortype == LCT_RGBA as c_int as c_uint {
            getPixelColorsRGBA8(out, numpixels, in_0, mode_in);
        } else if out_bitdepth == 8 && out_colortype == LCT_RGB as c_int as c_uint {
            getPixelColorsRGB8(out, numpixels, in_0, mode_in);
        } else {
            let mut r_0: c_uchar = 0;
            let mut g_0: c_uchar = 0;
            let mut b_0: c_uchar = 0;
            let mut a_0: c_uchar = 0;
            let mut i: size_t = 0;
            while i != numpixels {
                getPixelColorRGBA8(
                    &raw mut r_0,
                    &raw mut g_0,
                    &raw mut b_0,
                    &raw mut a_0,
                    in_0,
                    i,
                    mode_in,
                );
                error = rgba8ToPixel(out, i, mode_out, &raw mut tree, r_0, g_0, b_0, a_0);
                if error != 0 {
                    break;
                }
                i = i.wrapping_add(1);
            }
        }
    }

    if out_is_palette {
        color_tree_cleanup(&raw mut tree);
    }

    error
}

